function scheduleRefresh(expiresIn: number) {
  const ms = Math.max(0, (expiresIn - 60) * 1000);
  clearTimeout(refreshTimer);
  refreshTimer = setTimeout(refreshAccessToken, ms);
}

def test_rate_limit_blocks_sixth_attempt(client):
    for _ in range(5):
        client.post("/login", json=BAD_CREDS)
    res = client.post("/login", json=BAD_CREDS)
    assert res.status_code == 429
